const item = $input.first().json;
const claims = jwtVerify(item);
const body = item.body ?? {};
if (!body.draft_ids || !Array.isArray(body.draft_ids) || body.draft_ids.length === 0) throw new Error('400: draft_ids zorunlu');
if (body.draft_ids.length > 20) throw new Error('400: En fazla 20 taslak');
const validActions = ['approve', 'reject'];
if (!validActions.includes(body.action)) throw new Error('400: Geçersiz batch action');
return [{ json: { draft_ids: body.draft_ids, action: body.action, _sub: claims.sub } }];

const d = $input.first().json;
const esc = (s) => `'${String(s).replace(/'/g, "''")}'`;

let sql;
if (d.action === 'approve') {
  sql = `UPDATE drafts SET status='approved', reviewed_at=now() WHERE id=${esc(d.draft_id)} RETURNING id, status;`;
} else if (d.action === 'reject') {
  sql = `UPDATE drafts SET status='rejected', reviewed_at=now() WHERE id=${esc(d.draft_id)} RETURNING id, status;`;
} else if (d.action === 'edit') {
  const trimmed = String(d.content).trim().substring(0, 300);
  sql = `UPDATE drafts SET content=${esc(trimmed)}, status='edited', reviewed_at=now() WHERE id=${esc(d.draft_id)} RETURNING id, status;`;
}

return [{ json: { sql, draft_id: d.draft_id, action: d.action, _sub: d._sub } }];

const prev = $('Update SQL').first().json;
const esc = (s) => `'${String(s).replace(/'/g, "''")}'`;
const sql = `INSERT INTO audit_log (action, resource_type, resource_id, details)
VALUES (${esc(prev.action)}, 'draft', ${esc(prev.draft_id)}, '{}'::jsonb);`;
return [{ json: { sql } }];

const d = $input.first().json;
const esc = (s) => `'${String(s).replace(/'/g, "''")}'`;

const ids = d.draft_ids.map(id => esc(id)).join(',');
const newStatus = d.action === 'approve' ? 'approved' : 'rejected';
const sql = `UPDATE drafts SET status='${newStatus}', reviewed_at=now() WHERE id IN (${ids}) RETURNING id;`;

return [{ json: { sql, action: d.action, count: d.draft_ids.length, _sub: d._sub } }];

const prev = $('Batch SQL').first().json;
const updated = $input.all().length;
const esc = (s) => `'${String(s).replace(/'/g, "''")}'`;
